"""Hand-authored content of the learning path: stages, non-video units, gates, books.
Unit types: page (section in the library), practice, book, videos (a block from curate.py), note."""

def page(href, title, why, page_title=None):
    return dict(type='page', href=href, title=title, why=why, page=page_title)
def practice(title, why, dur=''):
    return dict(type='practice', title=title, why=why, dur=dur)
def book(key, parts='', why=''):
    return dict(type='book', key=key, parts=parts, why=why)
def videos(block, why=''):
    return dict(type='videos', block=block, why=why)
def note(text):
    return dict(type='note', text=text)

